import { ref, reactive, onMounted, onUnmounted, computed, nextTick } from 'vue';
import { useRouter, useRoute } from 'vue-router';
import { ArrowLeft, ChatDotRound, Heart, HeartFilled } from '@element-plus/icons-vue';
import { ElMessage, ElMessageBox } from 'element-plus';
import axios from 'axios';

// 初始化路由

export default {
  __name: 'CommentSuggestion',
  setup(__props, {
    expose: __expose
  }) {
    const router = useRouter();
    const route = useRoute();

    // 取消请求令牌（用于组件卸载时取消pending请求）
    const cancelSources = ref([]);

    // 创建axios实例
    const createRequest = () => {
      const request = axios.create({
        baseURL: '/api/v1',
        timeout: 10000,
        headers: {
          'Content-Type': 'application/json;charset=UTF-8'
        }
      });

      // 请求拦截器：添加登录凭证 + 取消令牌
      request.interceptors.request.use(config => {
        // 创建取消令牌
        const source = axios.CancelToken.source();
        config.cancelToken = source.token;
        cancelSources.value.push(source);

        // 添加用户信息
        const userInfo = JSON.parse(localStorage.getItem('userInfo') || '{"userId":"","username":""}');
        if (userInfo.userId && userInfo.username) {
          config.headers['X-User-ID'] = userInfo.userId;
          config.headers['X-Username'] = userInfo.username;
        }
        return config;
      }, error => Promise.reject(error));

      // 响应拦截器：统一处理结果
      request.interceptors.response.use(response => {
        const res = response.data;
        if (res.code !== 200) {
          ElMessage.error(res.msg || '操作失败');
          return Promise.reject(res);
        }
        return res;
      }, error => {
        // 忽略取消请求的错误
        if (axios.isCancel(error)) return Promise.reject(error);
        ElMessage.error(error.message || '网络异常，请稍后重试');
        return Promise.reject(error);
      });
      return request;
    };
    const request = createRequest();

    // 当前登录用户
    const currentUser = ref(JSON.parse(localStorage.getItem('userInfo') || '{"userId":"","username":""}'));
    const isLogin = computed(() => !!currentUser.value.userId);

    // 监听localStorage变化，同步用户状态
    const handleStorageChange = () => {
      currentUser.value = JSON.parse(localStorage.getItem('userInfo') || '{"userId":"","username":""}');
    };

    // 发布评论相关
    const publishContent = ref('');
    const isPublishing = ref(false);

    // 根评论相关
    const rootComments = ref([]);
    const rootPageInfo = reactive({
      page: 1,
      page_size: 10,
      total: 0
    });

    // 回复相关
    const showReplyId = ref(0);
    const replyContent = ref('');
    const isReplying = ref(false);
    const replyToUserId = ref('');
    const replyToUsername = ref('');
    const replyList = ref({});
    const replyPageInfo = reactive({});

    // 编辑评论相关
    const updateDialogVisible = ref(false);
    const updateContent = ref('');
    const updateCommentId = ref(0);
    const isUpdating = ref(false);

    // 格式化时间
    const formatTime = timeStr => {
      if (!timeStr) return '';
      try {
        const date = new Date(timeStr);
        const year = date.getFullYear();
        const month = ('0' + (date.getMonth() + 1)).slice(-2);
        const day = ('0' + date.getDate()).slice(-2);
        const hour = ('0' + date.getHours()).slice(-2);
        const minute = ('0' + date.getMinutes()).slice(-2);
        return `${year}-${month}-${day} ${hour}:${minute}`;
      } catch (e) {
        return '未知时间';
      }
    };

    // 获取根评论列表
    const getRootComments = async () => {
      try {
        const res = await request.post('/suggestion/root/page', {
          page: rootPageInfo.page,
          page_size: rootPageInfo.page_size
        });
        rootComments.value = res.data.list || [];
        rootPageInfo.total = res.data.total || 0;
        // 初始化点赞状态
        rootComments.value.forEach(item => {
          if (item.isLiked === undefined) item.isLiked = false;
        });
      } catch (err) {
        if (!axios.isCancel(err)) {
          console.error('获取根评论失败：', err);
        }
      }
    };

    // 获取指定根评论的回复列表
    const getReplyList = async rootId => {
      // 初始化分页信息
      if (!replyPageInfo[rootId]) {
        replyPageInfo[rootId] = {
          page: 1,
          page_size: 10,
          total: 0
        };
      }
      try {
        const res = await request.post('/suggestion/reply/page', {
          root_id: rootId,
          page: replyPageInfo[rootId].page,
          page_size: replyPageInfo[rootId].page_size
        });
        replyList.value[rootId] = res.data.list || [];
        replyPageInfo[rootId].total = res.data.total || 0;
        // 初始化点赞状态
        replyList.value[rootId].forEach(item => {
          if (item.isLiked === undefined) item.isLiked = false;
        });
      } catch (err) {
        if (!axios.isCancel(err)) {
          console.error(`获取根评论${rootId}的回复失败：`, err);
        }
      }
    };

    // 发布根评论
    const handlePublish = async () => {
      if (!publishContent.value.trim()) {
        return ElMessage.warning('评论内容不能为空');
      }
      if (!isLogin.value) {
        return ElMessage.warning('请先登录');
      }
      isPublishing.value = true;
      try {
        await request.post('/suggestion/publish', {
          content: publishContent.value.trim()
        });
        ElMessage.success('评论发布成功');
        publishContent.value = '';
        // 发布成功后回到第一页并滚动到顶部
        rootPageInfo.page = 1;
        await getRootComments();
        window.scrollTo({
          top: 0,
          behavior: 'smooth'
        });
      } catch (err) {
        if (!axios.isCancel(err)) {
          console.error('发布评论失败：', err);
        }
      } finally {
        isPublishing.value = false;
      }
    };

    // 点赞/取消点赞
    const handleLike = async (id, isLike) => {
      if (!isLogin.value) {
        return ElMessage.warning('请先登录');
      }
      try {
        const res = await request.post('/suggestion/like', {
          id,
          is_like: isLike
        });
        // 更新根评论点赞状态
        const rootIndex = rootComments.value.findIndex(item => item.id === id);
        if (rootIndex > -1) {
          rootComments.value[rootIndex].like_count = res.data.like_count;
          rootComments.value[rootIndex].isLiked = isLike;
        } else {
          // 更新回复点赞状态
          Object.keys(replyList.value).forEach(rootId => {
            const replyIndex = replyList.value[rootId].findIndex(item => item.id === id);
            if (replyIndex > -1) {
              replyList.value[rootId][replyIndex].like_count = res.data.like_count;
              replyList.value[rootId][replyIndex].isLiked = isLike;
            }
          });
        }
        ElMessage.success(isLike ? '点赞成功' : '取消点赞成功');
      } catch (err) {
        if (!axios.isCancel(err)) {
          console.error('点赞操作失败：', err);
        }
      }
    };

    // 切换回复面板显示
    const toggleReplyPanel = rootId => {
      showReplyId.value = rootId;
      if (rootId > 0) {
        // 重置分页数据
        if (replyPageInfo[rootId]) {
          replyPageInfo[rootId].page = 1;
        }
        getReplyList(rootId);
        replyToUserId.value = '';
        replyToUsername.value = '';
      }
      replyContent.value = '';
    };

    // 回复指定用户
    const replyToUser = (replyId, userId, username) => {
      replyToUserId.value = userId;
      replyToUsername.value = username;
      replyContent.value = `@${username} `;
      // 聚焦回复输入框
      nextTick(() => {
        const replyInput = document.querySelector('.reply-input .el-textarea__inner');
        if (replyInput) replyInput.focus();
      });
    };

    // 提交回复
    const handleReply = async rootId => {
      if (!replyContent.value.trim()) {
        return ElMessage.warning('回复内容不能为空');
      }
      if (!isLogin.value) {
        return ElMessage.warning('请先登录');
      }
      isReplying.value = true;
      try {
        await request.post('/suggestion/reply', {
          parent_id: rootId,
          reply_to_user_id: replyToUserId.value,
          reply_to_username: replyToUsername.value,
          content: replyContent.value.trim()
        });
        ElMessage.success('回复成功');
        replyContent.value = '';
        // 回复成功后重置分页并重新获取
        replyPageInfo[rootId].page = 1;
        await getReplyList(rootId);
        // 滚动到回复列表底部
        nextTick(() => {
          const replyList = document.querySelector(`.reply-list`);
          if (replyList) {
            replyList.scrollTop = replyList.scrollHeight;
          }
        });
      } catch (err) {
        if (!axios.isCancel(err)) {
          console.error('回复失败：', err);
        }
      } finally {
        isReplying.value = false;
      }
    };

    // 显示编辑弹窗
    const showUpdateDialog = (id, content) => {
      updateCommentId.value = id;
      updateContent.value = content;
      updateDialogVisible.value = true;
    };

    // 确认更新评论
    const handleUpdateConfirm = async () => {
      if (!updateContent.value.trim()) {
        return ElMessage.warning('评论内容不能为空');
      }
      if (!isLogin.value) {
        return ElMessage.warning('请先登录');
      }
      isUpdating.value = true;
      try {
        await request.post('/suggestion/update', {
          id: updateCommentId.value,
          content: updateContent.value.trim()
        });
        ElMessage.success('评论修改成功');
        updateDialogVisible.value = false;
        await getRootComments();
      } catch (err) {
        if (!axios.isCancel(err)) {
          console.error('更新评论失败：', err);
        }
      } finally {
        isUpdating.value = false;
      }
    };

    // 删除评论
    const handleDelete = async id => {
      try {
        await ElMessageBox.confirm('确定要删除这条评论吗？删除后无法恢复', '提示', {
          confirmButtonText: '确定',
          cancelButtonText: '取消',
          type: 'warning'
        });
        await request.post('/suggestion/delete', {
          id
        });
        ElMessage.success('评论删除成功');
        await getRootComments();
      } catch (err) {
        if (err !== 'cancel' && !axios.isCancel(err)) {
          console.error('删除评论失败：', err);
        }
      }
    };

    // 根评论分页事件
    const handleRootSizeChange = val => {
      rootPageInfo.page_size = val;
      getRootComments();
    };
    const handleRootPageChange = val => {
      rootPageInfo.page = val;
      getRootComments();
    };

    // 回复分页事件
    const handleReplySizeChange = (rootId, val) => {
      replyPageInfo[rootId].page_size = val;
      getReplyList(rootId);
    };
    const handleReplyPageChange = (rootId, val) => {
      replyPageInfo[rootId].page = val;
      getReplyList(rootId);
    };

    // 跳转到登录页
    const toLogin = () => {
      router.push({
        path: '/login',
        query: {
          redirect: route.fullPath
        }
      });
    };

    // 组件生命周期
    onMounted(() => {
      // 监听localStorage变化
      window.addEventListener('storage', handleStorageChange);
      // 初始化获取评论
      if (isLogin.value) {
        getRootComments();
      }
    });
    onUnmounted(() => {
      // 移除监听
      window.removeEventListener('storage', handleStorageChange);
      // 取消所有pending请求
      cancelSources.value.forEach(source => source.cancel('组件已卸载'));
      cancelSources.value = [];
    });

    // 暴露方法（按需）
    __expose({
      refreshComments: getRootComments
    });
    const __returned__ = {
      router,
      route,
      cancelSources,
      createRequest,
      request,
      currentUser,
      isLogin,
      handleStorageChange,
      publishContent,
      isPublishing,
      rootComments,
      rootPageInfo,
      showReplyId,
      replyContent,
      isReplying,
      replyToUserId,
      replyToUsername,
      replyList,
      replyPageInfo,
      updateDialogVisible,
      updateContent,
      updateCommentId,
      isUpdating,
      formatTime,
      getRootComments,
      getReplyList,
      handlePublish,
      handleLike,
      toggleReplyPanel,
      replyToUser,
      handleReply,
      showUpdateDialog,
      handleUpdateConfirm,
      handleDelete,
      handleRootSizeChange,
      handleRootPageChange,
      handleReplySizeChange,
      handleReplyPageChange,
      toLogin,
      ref,
      reactive,
      onMounted,
      onUnmounted,
      computed,
      nextTick,
      get useRouter() {
        return useRouter;
      },
      get useRoute() {
        return useRoute;
      },
      get ArrowLeft() {
        return ArrowLeft;
      },
      get ChatDotRound() {
        return ChatDotRound;
      },
      get Heart() {
        return Heart;
      },
      get HeartFilled() {
        return HeartFilled;
      },
      get ElMessage() {
        return ElMessage;
      },
      get ElMessageBox() {
        return ElMessageBox;
      },
      get axios() {
        return axios;
      }
    };
    Object.defineProperty(__returned__, '__isScriptSetup', {
      enumerable: false,
      value: true
    });
    return __returned__;
  }
};
